u0441\\u043a\\u0430\\u0447\\u0430\\u0442\\u044c \\u0432\\u0435\\u0441\\u0430 Phi-3-mini-4k-instruct \\u0438\\u043b\\u0438 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u044b \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e.\\n\\n\\u0412\\u044b\\u0432\\u043e\\u0434: \\u044d\\u0442\\u043e \\u0447\\u0438\\u0441\\u0442\\u043e \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d-\\u0437\\u0430\\u0434\\u0430\\u0447\\u0430 (design-only). \\u0417\\u0430\\u043f\\u0443\\u0441\\u043a \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438 \\u0437\\u0434\\u0435\\u0441\\u044c \\u0444\\u0438\\u0437\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u0435\\u043d \\u0438 \\u043d\\u0435 \\u0442\\u0440\\u0435\\u0431\\u0443\\u0435\\u0442\\u0441\\u044f; \\u043d\\u0438 \\u043e\\u0434\\u043d\\u0430 \\u0443\\u0441\\u043f\\u0435\\u0448\\u043d\\u0430\\u044f \\u043a\\u043e\\u043c\\u0430\\u043d\\u0434\\u0430 \\u043e\\u0441\\u043c\\u043e\\u0442\\u0440\\u0430 \\u043d\\u0435 \\u0442\\u0440\\u0430\\u043a\\u0442\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u043d\\u044b\\u0439 \\u044d\\u043a\\u0441\\u043f\\u0435\\u0440\\u0438\\u043c\\u0435\\u043d\\u0442. \\u041f\\u043e\\u043b\\u043d\\u044b\\u0439 \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d \\u0431\\u0443\\u0434\\u0435\\u0442 \\u0441\\u0430\\u043c\\u043e\\u0434\\u043e\\u0441\\u0442\\u0430\\u0442\\u043e\\u0447\\u043d\\u043e\\u0439 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0435\\u0439 \\u0434\\u043b\\u044f \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0435\\u0433\\u043e \\u0438\\u0441\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u044f \\u043d\\u0430 GPU-\\u0441\\u0442\\u0435\\u043d\\u0434\\u0435.\\n\\n## 2. \\u041f\\u0440\\u0435\\u0434\\u043b\\u0430\\u0433\\u0430\\u0435\\u043c\\u044b\\u0439 \\u043f\\u043e\\u0434\\u0445\\u043e\\u0434 \\u043a \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0443\\n\\n**\\u0426\\u0435\\u043b\\u044c:** \\u0438\\u0437\\u043e\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u0442\\u044c \\u044d\\u0444\\u0444\\u0435\\u043a\\u0442 \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 (RTN vs GPTQ) \\u0432\\u043d\\u0443\\u0442\\u0440\\u0438 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430 QuaRot \\u043d\\u0430 \\u043d\\u0435-LLAMA \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0435 Phi-3-mini-4k-instruct (3.8B, \\u0442\\u0440\\u0430\\u043d\\u0441\\u0444\\u043e\\u0440\\u043c\\u0435\\u0440-\\u0434\\u0435\\u043a\\u043e\\u0434\\u0435\\u0440, \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442 4096, HF-\\u0441\\u043e\\u0432\\u043c\\u0435\\u0441\\u0442\\u0438\\u043c\\u0430\\u044f `Phi3ForCausalLM`) \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 FP16-\\u044d\\u0442\\u0430\\u043b\\u043e\\u043d\\u0430 \\u0438 \\u043f\\u0440\\u043e\\u0442\\u0438\\u0432 LLAMA-\\u0440\\u0435\\u0437\\u0443\\u043b\\u044c\\u0442\\u0430\\u0442\\u043e\\u0432 \\u043e\\u0440\\u0438\\u0433\\u0438\\u043d\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 QuaRot.\\n\\n**\\u0421\\u0435\\u0442\\u043a\\u0430 \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u0439 + \\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0447\\u043a\\u0438:**\\n- \\u041c\\u043e\\u0434\\u0435\\u043b\\u044c-\\u043a\\u0430\\u043d\\u0434\\u0438\\u0434\\u0430\\u0442: `microsoft/Phi-3-mini-4k-instruct` (\\u043d\\u0435 128k-\\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 \\u2014 \\u0447\\u0442\\u043e\\u0431\\u044b \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u0442\\u044c \\u0432 \\u043e\\u043a\\u043d\\u0435 4K \\u0431\\u0435\\u0437 \\u0438\\u0437\\u043c\\u0435\\u043d\\u0435\\u043d\\u0438\\u044f RoPE).\\n- \\u041a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u044f: \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b QuaRot (\\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u043e\\u0435 \\u0441\\u0433\\u043b\\u0430\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 + \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d-\\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f, \\u0438\\u043d\\u0442\\u0435\\u0433\\u0440\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0432 embeddings/\\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0435 \\u0441\\u043b\\u043e\\u0438; \\u043e\\u043d\\u043b\\u0430\\u0439\\u043d-Hadamard \\u0432 attention); \\u0431\\u044d\\u043a\\u0435\\u043d\\u0434\\u044b \\u043e\\u043a\\u0440\\u0443\\u0433\\u043b\\u0435\\u043d\\u0438\\u044f RTN \\u0438 GPTQ; \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c W \\u2208 {4, 6, 8}; \\u0432\\u0441\\u0435 \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u0435 \\u0441\\u043b\\u043e\\u0438 (attention + MLP); group-wise (G=128) \\u0434\\u043b\\u044f 4/6-bit, per-channel \\u0434\\u043b\\u044f 8-bit; layernorm/embeddings/lm_head \\u2014 FP16.\\n- \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0442\\u043e\\u0447\\u043a\\u0438: (a) FP16 Phi-3-mini-4k-instruct (\\u0432\\u0435\\u0440\\u0445\\u043d\\u044f\\u044f \\u0433\\u0440\\u0430\\u043d\\u0438\\u0446\\u0430); (b) \\u00ab\\u043d\\u0430\\u0438\\u0432\\u043d\\u044b\\u0435\\u00bb RTN/GPTQ \\u0431\\u0435\\u0437 \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u0439 QuaRot \\u2014 \\u043e\\u0442\\u0434\\u0435\\u043b\\u0438\\u0442\\u044c \\u0432\\u043a\\u043b\\u0430\\u0434 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438 \\u043e\\u0442 \\u0432\\u043a\\u043b\\u0430\\u0434\\u0430 \\u043c\\u0435\\u0442\\u043e\\u0434\\u0430 \\u043e\\u043a\\u0440\\u0443\\u0433\\u043b\\u0435\\u043d\\u0438\\u044f; (c) LLAMA-2-7B \\u0432 \\u0442\\u0435\\u0445 \\u0436\\u0435 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0430\\u0445 \\u043d\\u0430 \\u0442\\u043e\\u043c \\u0436\\u0435 \\u043a\\u043e\\u0434\\u0435 + \\u0447\\u0438\\u0441\\u043b\\u0435\\u043d\\u043d\\u044b\\u0435 \\u0437\\u043d\\u0430\\u0447\\u0435\\u043d\\u0438\\u044f \\u0438\\u0437 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 QuaRot \\u043a\\u0430\\u043a \\u0432\\u043d\\u0435\\u0448\\u043d\\u0438\\u0439 \\u0440\\u0435\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 (\\u043f\\u0435\\u0440\\u0435\\u043d\\u043e\\u0441\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u0430 \\u043c\\u0435\\u0436\\u0434\\u0443 \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430\\u043c\\u0438).\\n- \\u041e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f \\u043e\\u0441\\u044c \\u2014 weight-only; \\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f \\u043e\\u0441\\u044c (\\u043f\\u043e \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044e) \\u2014 W4A4KV4 \\u043a\\u0430\\u043a \\u0441\\u0438\\u0433\\u043d\\u0430\\u0442\\u0443\\u0440\\u043d\\u044b\\u0439 \\u0440\\u0435\\u0436\\u0438\\u043c QuaRot.\\n\\n**\\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438:**\\n- Perplexity: WikiText-103 (\\u043e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f) + Pile validation (\\u0432\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f), \\u043d\\u0435\\u043f\\u0440\\u0435\\u0440\\u044b\\u0432\\u043d\\u043e\\u0435 (non-overlapping) \\u043e\\u043a\\u043d\\u043e 4096 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432 = \\u0434\\u043b\\u0438\\u043d\\u0430 \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442\\u0430; \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c \\u2014 2048-\\u043e\\u043a\\u043e\\u043d\\u043d\\u044b\\u0439 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d.\\n- Zero-shot accuracy: lm-evaluation-harness: PIQA, ARC-e, ARC-c, HellaSwag, WinoGrande, LAMBADA (0-shot; LAMBADA/MMLU 5-shot \\u043f\\u043e \\u043a\\u043e\\u043d\\u0432\\u0435\\u043d\\u0446\\u0438\\u0438); MMLU 5-shot \\u0434\\u043e\\u043f\\u043e\\u043b\\u043d\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e \\u043a\\u0430\\u043a \\u0438\\u043d\\u0434\\u0438\\u043a\\u0430\\u0442\\u043e\\u0440 \\u0434\\u0435\\u0433\\u0440\\u0430\\u0434\\u0430\\u0446\\u0438\\u0438 \\u0437\\u043d\\u0430\\u043d\\u0438\\u0439; stderr/\\u0431\\u0443\\u0442\\u0441\\u0442\\u0440\\u044d\\u043f.\\n\\n**\\u0410\\u043d\\u0430\\u043b\\u0438\\u0437:**\\n- \\u0394PPL \\u0438 \\u0394accuracy \\u043e\\u0442\\u043d\\u043e\\u0441\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e FP16 \\u0432 \\u043a\\u0430\\u0436\\u0434\\u043e\\u0439 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0435 (\\u043c\\u0435\\u0442\\u043e\\u0434 \\u00d7 \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c); \\u0441\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u0440\\u0430\\u043d\\u0436\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f RTN vs GPTQ \\u043f\\u043e \\u0431\\u0438\\u0442\\u043d\\u043e\\u0441\\u0442\\u044f\\u043c.\\n- \\u0421\\u0440\\u0430\\u0432\\u043d\\u0435\\u043d\\u0438\\u0435 \\u00ab\\u0434\\u0435\\u043b\\u044c\\u0442\\u0430-\\u043a\\u0440\\u0438\\u0432\\u044b\\u0445\\u00bb Phi-3 vs LLAMA-2-7B \\u043f\\u0440\\u0438 \\u043e\\u0434\\u0438\\u043d\\u0430\\u043a\\u043e\\u0432\\u044b\\u0445 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0430\\u0445 \\u2014 \\u043f\\u0440\\u044f\\u043c\\u043e\\u0439 \\u043e\\u0442\\u0432\\u0435\\u0442 \\u043d\\u0430 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441 \\u043e \\u0433\\u0435\\u043d\\u0435\\u0440\\u0430\\u043b\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438.\\n- \\u0410\\u0431\\u043b\\u044f\\u0446\\u0438\\u044f \\u0432\\u043a\\u043b\\u0430\\u0434\\u043e\\u0432: \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f on/off \\u00d7 RTN/GPTQ (2\\u00d72 \\u043f\\u0440\\u0438 4-bit).\\n- \\u0412\\u0430\\u043b\\u0438\\u0434\\u0430\\u0446\\u0438\\u044f \\u043f\\u0440\\u0435\\u0434\\u043f\\u043e\\u0441\\u044b\\u043b\\u043e\\u043a QuaRot \\u043d\\u0430 Phi-3: \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a\\u0430 outlier-\\u043a\\u0430\\u043d\\u0430\\u043b\\u043e\\u0432 \\u0432\\u0435\\u0441\\u043e\\u0432/\\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0439 \\u0434\\u043e/\\u043f\\u043e\\u0441\\u043b\\u0435 \\u0441\\u0433\\u043b\\u0430\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u044f \\u0438 \\u0440\\u043e\\u0442\\u0430\\u0446\\u0438\\u0438 (\\u043e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435 \\u043e\\u0436\\u0438\\u0434\\u0430\\u0435\\u043c\\u043e\\u0433\\u043e \\u043f\\u043e\\u0432\\u0435\\u0434\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438 QKV-bias \\u0438 \\u0438\\u043d\\u043e\\u043c \\u043f\\u0440\\u043e\\u0444\\u0438\\u043b\\u0435 \\u0430\\u043a\\u0442\\u0438\\u0432\\u0430\\u0446\\u0438\\u0439).\\n\\n**\\u041e\\u0441\\u0443\\u0449\\u0435\\u0441\\u0442\\u0432\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c:** \\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u044f \\u0440\\u0430\\u0441\\u0441\\u0447\\u0438\\u0442\\u0430\\u043d\\u0430 \\u043d\\u0430 1\\u00d780GB GPU (3.8B: \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 \\u0438 \\u0438\\u043d\\u0444\\u0435\\u0440\\u0435\\u043d\\u0441 \\u0432 FP16 \\u043f\\u043e\\u043c\\u0435\\u0449\\u0430\\u044e\\u0442\\u0441\\u044f; \\u0413\\u0435\\u0441\\u0441\\u0435\\u043d\\u044b GPTQ \\u2014 \\u043f\\u043e \\u0447\\u0430\\u043d\\u043a\\u0430\\u043c). \\u0412 \\u0442\\u0435\\u043a\\u0443\\u0449\\u0435\\u0439 CPU-\\u0441\\u0440\\u0435\\u0434\\u0435 \\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u0435\\u043d \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0435\\u0440\\u0435\\u0441\\u043c\\u043e\\u0442\\u0440 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u0439 \\u0431\\u0435\\u0437 \\u0432\\u0435\\u0441\\u043e\\u0432; \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u0435\\u043d\\u0438\\u0435 \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u043e\\u0432 \\u0437\\u0434\\u0435\\u0441\\u044c \\u043d\\u0435\\u0432\\u043e\\u0437\\u043c\\u043e\\u0436\\u043d\\u043e \\u0438 \\u043d\\u0435 \\u0437\\u0430\\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f.\\n\\n## 3. Consequential assumptions \\u0438 \\u043d\\u0435\\u043e\\u043f\\u0440\\u0435\\u0434\\u0435\\u043b\\u0451\\u043d\\u043d\\u043e\\u0441\\u0442\\u0438 \\u2014 \\u0432 \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u043d\\u044b\\u0445 \\u043f\\u043e\\u043b\\u044f\\u0445\\n\\n\\u041d\\u0438 \\u043e\\u0434\\u043d\\u043e \\u044d\\u043c\\u043f\\u0438\\u0440\\u0438\\u0447\\u0435\\u0441\\u043a\\u043e\\u0435 \\u043e\\u0436\\u0438\\u0434\\u0430\\u043d\\u0438\\u0435 (\\u0432 \\u0434\\u0443\\u0445\\u0435 \\u00abGPTQ \\u043b\\u0443\\u0447\\u0448\\u0435 RTN \\u043d\\u0430 N \\u043f\\u043f\\u00bb) \\u043d\\u0435 \\u0443\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0430\\u0435\\u0442\\u0441\\u044f; \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u044b \\u0431\\u0443\\u0434\\u0443\\u0442 \\u0441\\u0444\\u043e\\u0440\\u043c\\u0443\\u043b\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b \\u043a\\u0430\\u043a \\u0442\\u0435\\u0441\\u0442\\u0438\\u0440\\u0443\\u0435\\u043c\\u044b\\u0435 \\u0432 \\u043f\\u043e\\u043b\\u043d\\u043e\\u043c \\u0434\\u0438\\u0437\\u0430\\u0439\\u043d\\u0435. \\u0413\\u043e\\u0442\\u043e\\u0432 \\u043f\\u0435\\u0440\\u0435\\u0439\\u0442\\u0438 \\u043a stage=result \\u043f\\u043e\\u0441\\u043b\\u0435 \\u0432\\u0430\\u0448\\u0435\\u0433\\u043e \\u043f\\u043e\\u0434\\u0442\\u0432\\u0435\\u0440\\u0436\\u0434\\u0435\\u043d\\u0438\\u044f \\u0438 \\u0443\\u0442\\u043e\\u0447\\u043d\\u0435\\u043d\\u0438\\u0439 \\u043f\\u043e \\u0442\\u0435\\u043c\\u0430\\u043c setup_1/3/4/6/8/11.\", \"assumptions\": [\"\\u0417\\u0430\\u0434\\u0430\\u0447\\u0430 design-only: \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u044b \\u0432\\u044b\\u043f\\u043e\\u043b\\u043d\\u044f\\u044e\\u0442\\u0441\\u044f \\u0432\\u043d\\u0435 \\u044d\\u0442\\u043e\\u0439 \\u0441\\u0440\\u0435\\u0434\\u044b; \\u04