5\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439 \\u2014 completion-\\u0440\\u0435\\u0436\\u0438\\u043c (\\u0431\\u0435\\u0437 chat-\\u0448\\u0430\\u0431\\u043b\\u043e\\u043d\\u0430), \\u043b\\u043e\\u0433\\u043b\\u0438\\u0442-\\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 \\u0432 harness; \\u044d\\u0442\\u043e \\u0438\\u043d\\u0433\\u0435\\u0440\\u0435\\u043d\\u0442\\u043d\\u043e \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u0443 (\\u043c\\u043e\\u0434\\u0435\\u043b\\u044c instruct, \\u0430 \\u0431\\u0435\\u043d\\u0447\\u043c\\u0430\\u0440\\u043a\\u0438 completion) \\u0438 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u0443\\u0435\\u0442\\u0441\\u044f \\u043a\\u0430\\u043a \\u043e\\u0433\\u0440\\u0430\\u043d\\u0438\\u0447\\u0435\\u043d\\u0438\\u0435.\\n\\n## 3. \\u0422\\u043e\\u0447\\u043d\\u044b\\u0435 \\u043a\\u043e\\u043d\\u0444\\u0438\\u0433\\u0443\\u0440\\u0430\\u0446\\u0438\\u0438 (\\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 \\u0440\\u0435\\u0448\\u0435\\u043d\\u0438\\u044f)\\n\\n**\\u041f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b QuaRot (\\u043e\\u0431\\u0449\\u0438\\u0439 \\u0434\\u043b\\u044f \\u043e\\u0431\\u0435\\u0438\\u0445 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439):** \\u043f\\u0435\\u0440-\\u0432\\u0435\\u043a\\u0442\\u043e\\u0440\\u043d\\u043e\\u0435 \\u0441\\u0433\\u043b\\u0430\\u0436\\u0438\\u0432\\u0430\\u043d\\u0438\\u0435 \\u0432\\u0435\\u0441\\u043e\\u0432 (spherical/adaptive \\u03b1), \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d-\\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f R:\\u878d\\u5408 \\u0432 embeddings (input) \\u0438 \\u0432 W_down/W_out (output), \\u043e\\u043d\\u043b\\u0430\\u0439\\u043d-\\u0430\\u0434\\u0430\\u043f\\u0442\\u0438\\u0432\\u043d\\u044b\\u0435 Hadamard \\u0434\\u043b\\u044f attention-\\u043f\\u0443\\u0442\\u0438 (V\\u2192O \\u0438 QK-\\u043f\\u0443\\u0442\\u044c). \\u0412\\u0441\\u0435 \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f \\u2014 \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0435 Hadamard-\\u0431\\u043b\\u043e\\u043a\\u0438, \\u0433\\u0435\\u043d\\u0435\\u0440\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0438\\u0437 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e seed.\\n**\\u0420\\u0435\\u0448\\u0435\\u043d\\u0438\\u0435 \\u043f\\u043e QKV-bias Phi-3 (\\u0437\\u0430\\u043a\\u0440\\u044b\\u0442\\u043e, \\u043d\\u0435 \\u043e\\u0442\\u043a\\u0440\\u044b\\u0442\\u044b\\u0439 \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441):** \\u0442\\u0435\\u043d\\u0437\\u043e\\u0440\\u044b bias (\\u0443 Phi-3 bias \\u0435\\u0441\\u0442\\u044c \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u0432 qkv_proj; MLP \\u0438 o_proj \\u2014 \\u0431\\u0435\\u0437 bias) **\\u043d\\u0435 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0443\\u044e\\u0442\\u0441\\u044f \\u0438 \\u0432\\u044b\\u0447\\u0438\\u0441\\u043b\\u044f\\u044e\\u0442\\u0441\\u044f \\u0432 FP16 \\u0432 \\u0438\\u0441\\u0445\\u043e\\u0434\\u043d\\u043e\\u043c \\u043f\\u0440\\u043e\\u0441\\u0442\\u0440\\u0430\\u043d\\u0441\\u0442\\u0432\\u0435**. \\u041e\\u0431\\u043e\\u0441\\u043d\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435: \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438\\u043c\\u0435\\u043d\\u0438\\u043c\\u044b \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043a \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u044b\\u043c (\\u0432\\u0435\\u0441\\u043e\\u0432\\u044b\\u043c) \\u043e\\u0442\\u043e\\u0431\\u0440\\u0430\\u0436\\u0435\\u043d\\u0438\\u044f\\u043c, \\u0438\\u043d\\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442\\u043d\\u043e\\u0441\\u0442\\u044c \\u0441\\u043e\\u0445\\u0440\\u0430\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u043f\\u0440\\u0438 \\u0434\\u043e\\u0431\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u0438 bias \\u043f\\u043e\\u0441\\u043b\\u0435 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0433\\u043e \\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u043e\\u0433\\u043e \\u0441\\u043b\\u043e\\u044f; \\u044d\\u0442\\u043e \\u0440\\u043e\\u0432\\u043d\\u043e \\u0442\\u043e\\u0442 \\u043f\\u0443\\u0442\\u044c, \\u043a\\u043e\\u0442\\u043e\\u0440\\u044b\\u043c QuaRot \\u0442\\u0440\\u0430\\u043a\\u0442\\u0443\\u0435\\u0442 \\u043d\\u0435\\u0438\\u0437\\u0432\\u043b\\u0435\\u043a\\u0430\\u0435\\u043c\\u044b\\u0435 \\u043d\\u0435\\u043b\\u0438\\u043d\\u0435\\u0439\\u043d\\u043e\\u0441\\u0442\\u0438; \\u0434\\u043e\\u043b\\u044f \\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u043e\\u0432 <0.05%, \\u0432\\u043b\\u0438\\u044f\\u043d\\u0438\\u0435 \\u043d\\u0430 \\u0431\\u0438\\u0442-\\u0431\\u044e\\u0434\\u0436\\u0435\\u0442 \\u043d\\u0438\\u0447\\u0442\\u043e\\u0436\\u043d\\u043e; \\u0430\\u043b\\u044c\\u0442\\u0435\\u0440\\u043d\\u0430\\u0442\\u0438\\u0432\\u0430 (\\u0441\\u0434\\u0432\\u0438\\u0433 bias \\u0432 rotated space) \\u043c\\u0430\\u0442\\u0435\\u043c\\u0430\\u0442\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438 \\u043d\\u0435\\u043a\\u043e\\u0440\\u0440\\u0435\\u043a\\u0442\\u043d\\u0430 \\u0434\\u043b\\u044f Q/K, \\u0442.\\u043a. bias \\u0432\\u0445\\u043e\\u0434\\u0438\\u0442 \\u0432 \\u0441\\u043a\\u0430\\u043b\\u044f\\u0440\\u043d\\u044b\\u0435 scores \\u0434\\u043e \\u0432\\u0441\\u044f\\u043a\\u0438\\u0445 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u0443\\u044e\\u0449\\u0438\\u0445 \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u0439. \\u0412\\u043d\\u043e\\u0441\\u0438\\u0442\\u0441\\u044f \\u0432 \\u0440\\u0435\\u0435\\u0441\\u0442\\u0440 \\u0440\\u0438\\u0441\\u043a\\u043e\\u0432 (R2) \\u0438 \\u0432 \\u0430\\u0431\\u043b\\u044f\\u0446\\u0438\\u044e: \\u0432\\u0430\\u0440\\u0438\\u0430\\u043d\\u0442 \\u00ab\\u0441\\u043b\\u043e\\u0438 \\u0441 bias \\u043f\\u043e\\u043b\\u043d\\u043e\\u0441\\u0442\\u044c\\u044e \\u043c\\u0430\\u0441\\u043a\\u0438\\u0440\\u0443\\u044e\\u0442\\u0441\\u044f \\u0438\\u0437 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438\\u00bb \\u043f\\u0440\\u043e\\u0433\\u043e\\u043d\\u044f\\u0435\\u0442\\u0441\\u044f \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0440\\u0438 4-bit (2 \\u044f\\u0447\\u0435\\u0439\\u043a\\u0438, Phi-3, GPTQ) \\u043a\\u0430\\u043a \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u044c.\\n**FP16-\\u043e\\u0441\\u0442\\u0430\\u0442\\u043a\\u0438 (\\u043e\\u0431\\u0435 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0438):** embeddings (\\u043f\\u043e\\u0441\\u043b\\u0435 \\u0444\\u044c\\u044e\\u0437\\u0430 \\u0432\\u0440\\u0430\\u0449\\u0435\\u043d\\u0438\\u044f \\u2014 \\u0442\\u043e\\u0447\\u043d\\u043e\\u0435 \\u0443\\u043c\\u043d\\u043e\\u0436\\u0435\\u043d\\u0438\\u0435), lm_head, \\u0432\\u0441\\u0435 RMSNorm, bias, RoPE.\\n**\\u0421\\u0435\\u0442\\u043a\\u0430 \\u043a\\u0432\\u0430\\u043d\\u0442\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438 (\\u0438\\u0434\\u0435\\u043d\\u0442\\u0438\\u0447\\u043d\\u0430 \\u0434\\u043b\\u044f RTN \\u0438 GPTQ \\u2014 \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u044f \\u043e\\u0431\\u044f\\u0437\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u0430):** \\u0430\\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f \\u0430\\u0444\\u0444\\u0438\\u043d\\u043d\\u0430\\u044f \\u0441\\u0435\\u0442\\u043a\\u0430 per-group min-max, G=128 \\u0434\\u043b\\u044f 4/6-bit; per-channel (G=hidden) \\u0434\\u043b\\u044f 8-bit; \\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f \\u0441\\u0435\\u0442\\u043a\\u0430 \\u0441 zero-point=0 \\u043d\\u0435 \\u0434\\u043e\\u043f\\u0443\\u0441\\u043a\\u0430\\u0435\\u0442\\u0441\\u044f, \\u0435\\u0441\\u043b\\u0438 \\u043d\\u0435 \\u0432\\u043a\\u043b\\u044e\\u0447\\u0435\\u043d\\u0430 \\u0434\\u043b\\u044f \\u043e\\u0431\\u043e\\u0438\\u0445 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u0432. \\u041e\\u0442\\u043b\\u0438\\u0447\\u0438\\u0435 \\u043c\\u0435\\u0442\\u043e\\u0434\\u043e\\u0432 \\u2014 \\u0442\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u0440\\u0430\\u0432\\u0438\\u043b\\u043e \\u043e\\u043a\\u0440\\u0443\\u0433\\u043b\\u0435\\u043d\\u0438\\u044f: RTN = nearest \\u043d\\u0430 \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u043e\\u0439 \\u0441\\u0435\\u0442\\u043a\\u0435 (\\u0431\\u0435\\u0437 optimal-clipping/MAPE-\\u0442\\u0440\\u044e\\u043a\\u043e\\u0432); GPTQ = OBQ/GPTQ-\\u043a\\u043e\\u043c\\u043f\\u0435\\u043d\\u0441\\u0430\\u0446\\u0438\\u044f \\u043e\\u0448\\u0438\\u0431\\u043a\\u0438 \\u043d\\u0430 \\u0442\\u043e\\u0439 \\u0436\\u0435 \\u0441\\u0435\\u0442\\u043a\\u0435.\\n**\\u0413\\u0438\\u043f\\u0435\\u0440\\u043f\\u0430\\u0440\\u0430\\u043c\\u0435\\u0442\\u0440\\u044b GPTQ (common-default, \\u0437\\u0430\\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u044b):** percdamp=0.01, act-order=True, static_groups=False, block-size=128, \\u043a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043e\\u0447\\u043d\\u044b\\u0439 batch=1, seq=2048.\\n**\\u041a\\u0430\\u043b\\u0438\\u0431\\u0440\\u043e\\u0432\\u043a\\u0430 (\\u0441\\u0438\\u043c\\u043c\\u0435\\u0442\\u0440\\u0438\\u044f \\u2014 \\u0442\\u0440\\u0435\\u0431\\u043e\\u0432\\u0430\\u043d\\u0438\\u0435, \\u043d\\u0435 \\u0433\\u0438\\u043f\\u043e\\u0442\\u0435\\u0437\\u0430):** C4, 128 \\u043f\\u043e\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0435\\u0439 \\u00d7 2048 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432, \\u043e\\u0434\\u0438\\u043d \\u0438 \\u0442\\u043e\\u0442 \\u0436\\u0435 \\u0444\\u0430\\u0439\\u043b-\\u0441\\u043d\\u0438\\u043c\\u043e\\u043a \\u0438 seed=4242 \\u0434\\u043b\\u044f RTN, GPTQ \\u0438 \\u0441\\u0431\\u043e\\u0440\\u0430 \\u0441\\u0442\\u0430\\u0442\\u0438\\u0441\\u0442\\u0438\\u043a; RTN \\u043d\\u0435 \\u0438\\u0441\\u043f\\u043e\\u043b\\u044c\\u0437\\u0443\\u0435\\u0442 \\u0434\\u0430\\u043d\\u043d\\u044b\\u0445 \\u043f\\u043e\\u043c\\u0438\\u043c\\u043e \\u0442\\u0435\\u0445 \\u0436\\u0435 128\\u00d72048 (\\u0434\\u043b\\u044f \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438 min-max).\\n**\\u0412\\u0435\\u0440\\u0441\\u0438\\u0438 \\u041f\\u041e (\\u043f\\u0438\\u043d\\u044b \\u0432 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0444\\u0438\\u043a\\u0430\\u0446\\u0438\\u0438):** \\u043e\\u0434\\u0438\\u043d commit \\u0440\\u0435\\u043f\\u043e\\u0437\\u0438\\u0442\\u043e\\u0440\\u0438\\u044f QuaRot (\\u043f\\u043e\\u0441\\u043b\\u0435 \\u043f\\u043e\\u0440\\u0442\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f Phi3), transformers \\u22654.43 (\\u043f\\u043e\\u0434\\u0434\\u0435\\u0440\\u0436\\u043a\\u0430 `Phi3ForCausalLM`), torch 2.3.x, \\u0444\\u0438\\u043a\\u0441\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 commit lm-evaluation-harness (\\u043e\\u0434\\u0438\\u043d \\u0431\\u0438\\u043b\\u0434 \\u0434\\u043b\\u044f \\u0432\\u0441\\u0435\\u0445 28 \\u044f\\u0447\\u0435\\u0435\\u043a), \\u0432\\u0435\\u0440\\u0441\\u0438\\u0438 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442\\u043e\\u0432 \\u043f\\u043e hash.\\n\\n## 4. \\u041c\\u0435\\u0442\\u0440\\u0438\\u043a\\u0438 \\u0438 \\u043f\\u0440\\u043e\\u0442\\u043e\\u043a\\u043e\\u043b\\u044b \\u043e\\u0446\\u0435\\u043d\\u043a\\u0438\\n\\n**Perplexity (\\u043d\\u0430 \\u043a\\u0430\\u0436\\u0434\\u044b\\u0439 \\u0447\\u0435\\u043a\\u043f\\u043e\\u0439\\u043d\\u0442):**\\n- \\u041e\\u0441\\u043d\\u043e\\u0432\\u043d\\u0430\\u044f: WikiText-103 (`wikitext-103-raw-v1`, test), non-overlapping \\u043e\\u043a\\u043d\\u043e **4096** (2048 \\u0434\\u043b\\u044f LLAMA-\\u043a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044f \\u2014 \\u0442\\u043e\\u0436\\u0435 4096, \\u043a\\u043e\\u043d\\u0442\\u0435\\u043a\\u0441\\u0442 \\u043f\\u043e\\u0437\\u0432\\u043e\\u043b\\u044f\\u0435\\u0442; \\u043e\\u043a\\u043d\\u0430 \\u0432\\u044b\\u0440\\u0430\\u0432\\u043d\\u0438\\u0432\\u0430\\u044e\\u0442\\u0441\\u044f \\u043c\\u0435\\u0436\\u0434\\u0443 \\u043c\\u043e\\u0434\\u0435\\u043b\\u044f\\u043c\\u0438).\\n- \\u041a\\u043e\\u043d\\u0442\\u0440\\u043e\\u043b\\u044c \\u0447\\u0443\\u0432\\u0441\\u0442\\u0432\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u043e\\u0441\\u0442\\u0438: \\u0442\\u043e\\u0442 \\u0436\\u0435 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442, \\u043e\\u043a\\u043d\\u043e 2048.\\n- \\u0412\\u0442\\u043e\\u0440\\u0438\\u0447\\u043d\\u0430\\u044f: Pile validation, \\u0434\\u0435\\u0442\\u0435\\u0440\\u043c\\u0438\\u043d\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043d\\u044b\\u0439 \\u043f\\u043e\\u0434\\u6837\\u672c \\u0438\\u0437 256 \\u0434\\u043e\\u043a\\u0443\\u043c\\u0435\\u043d\\u0442\\u043e\\u0432 \\u043f\\u043e 4096 \\u0442\\u043e\\u043a\\u0435\\u043d\\u043e\\u0432.\\n- \\u0421\\u043e\\u0432\\u043c\\u0435\\u0441\\u0442\\u0438\\u043c\\u043e\\u0441\\u0442\\u044c \\u0441\\u043e \\u0441\\u0442\\u0430\\u0442\\u044c\\u0451\\u0439: WikiText-2 (`wikitext-2-raw-v1`, \\u043e\\u043a\\u043d\\u043e 4096) \\u2014 \\u0442\\u0440\\u0435\\u0442\\u0438\\u0439 \\u0434\\u0430\\u0442\\u0430\\u0441\\u0435\\u0442 \\u0441\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u044c\\u043d\\u043e \\u0434\\u043b\\u044f \\u0441\\u0432\\u0435\\u0440\\u043a\\u0438 \\u0441 \\u0447\\u0438\\u0441\\u043b\\u0430\\u043c\\u0438 QuaRot (\\u0432 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0435, \\u043d\\u0430\\u0441\\u043a\\u043e\\u043b\\u044c\\u043a\\u043e \\u043f\\u043e\\u043c\\u043d\\u044e, WikiText-2; \\u043d\\u0435 \\u0432\\u0435\\u0440\\u0438\\u0444\\u0438\\u0446\\u0438\\u0440\\u043e\\u0432\\u0430\\u043d\\u043e \\u043e\\u0444\\u043b\\u0430\\u0439\\u043d \\u2192 \\u0440\\u0438\\u0441\\u043a R6). \\u041b\\u044e\\u0431\\u0430\\u044f \\u0441\\u0432\\u0435\\u0440\\u043a\\u0430 \\u0441 \\u0447\\u0438\\u0441\\u043b\\u0430\\u043c\\u0438 \\u0441\\u0442\\u0430\\u0442\\u044c\\u0438 \\u0441\\u043e\\u043f\\u0440\\u043e